"""Bring up robot_state_publisher, joint_state_publisher and move_group for the
simple 3-joint revolute 'arm3' robot, with the 'arm' planning group."""

from pathlib import Path

from launch import LaunchDescription
from launch_ros.actions import Node
from launch_param_builder import load_yaml

PKG_DIR = Path(__file__).resolve().parent.parent


def _merged_ompl_config():
    from ament_index_python.packages import get_package_share_directory

    defaults_dir = Path(get_package_share_directory("moveit_configs_utils")) / "default_configs"
    ompl_config = load_yaml(defaults_dir / "ompl_planning.yaml")
    ompl_config.update(load_yaml(defaults_dir / "ompl_defaults.yaml"))
    return ompl_config


def generate_launch_description():
    urdf_path = PKG_DIR / "urdf" / "arm.urdf"
    srdf_path = PKG_DIR / "config" / "arm.srdf"

    robot_description_content = urdf_path.read_text()
    robot_description_semantic_content = srdf_path.read_text()

    robot_description = {"robot_description": robot_description_content}
    robot_description_semantic = {
        "robot_description_semantic": robot_description_semantic_content
    }
    kinematics_yaml = load_yaml(PKG_DIR / "config" / "kinematics.yaml")
    robot_description_kinematics = {"robot_description_kinematics": kinematics_yaml}

    joint_limits_yaml = load_yaml(PKG_DIR / "config" / "joint_limits.yaml")
    robot_description_planning = {"robot_description_planning": joint_limits_yaml}

    planning_pipelines = {
        "planning_pipelines": ["ompl"],
        "default_planning_pipeline": "ompl",
        "ompl": _merged_ompl_config(),
    }

    planning_scene_monitor_parameters = {
        "publish_planning_scene": True,
        "publish_geometry_updates": True,
        "publish_state_updates": True,
        "publish_transforms_updates": True,
    }

    move_group_capabilities = {
        "capabilities": "",
        "disable_capabilities": "",
    }

    move_group_node = Node(
        package="moveit_ros_move_group",
        executable="move_group",
        output="screen",
        parameters=[
            robot_description,
            robot_description_semantic,
            robot_description_kinematics,
            robot_description_planning,
            planning_pipelines,
            planning_scene_monitor_parameters,
            move_group_capabilities,
            {
                "allow_trajectory_execution": False,
                "publish_robot_description_semantic": True,
                "use_sim_time": False,
            },
        ],
    )

    robot_state_publisher_node = Node(
        package="robot_state_publisher",
        executable="robot_state_publisher",
        output="screen",
        parameters=[robot_description, {"use_sim_time": False}],
    )

    joint_state_publisher_node = Node(
        package="joint_state_publisher",
        executable="joint_state_publisher",
        output="screen",
        parameters=[robot_description, {"use_sim_time": False}],
    )

    return LaunchDescription(
        [
            robot_state_publisher_node,
            joint_state_publisher_node,
            move_group_node,
        ]
    )

